local PruningShearsMaker = {}
local PRODUCTS = {
    iron_shears = { name = "Železne škarje za obrezovanje", ironCost = 2, woodCost = 1, leatherCost = 1, time = 5, cost = 130, prestige = 2, happiness = 1, description = "Železne škarje za obrezovanje vrtnih rastlin." },
    bronze_shears = { name = "Bronaste škarje za obrezovanje", bronzeCost = 2, ironCost = 1, woodCost = 1, leatherCost = 1, time = 7, cost = 320, prestige = 4, happiness = 2, description = "Bronaste škarje za trši les." },
    silver_shears = { name = "Srebrne škarje za obrezovanje", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 1, time = 11, cost = 780, prestige = 9, happiness = 3, description = "Srebrne škarje za plemiške vrtove." },
    gilded_shears = { name = "Pozlačene škarje za obrezovanje", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 15, cost = 1700, prestige = 18, happiness = 4, description = "Pozlačene škarje za dvorne vrtove." },
    jewel_set_shears = { name = "Draguljaste škarje za obrezovanje", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 19, cost = 3700, prestige = 33, happiness = 6, description = "Draguljaste škarje za kraljeve vrtove." },
    royal_sovereign_shears = { name = "Kraljevski suverene škarje za obrezovanje", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 26, cost = 8000, prestige = 65, happiness = 12, description = "Suverene škarje z biseri za krono." },
}
local BUILDINGS = {
    shears_workshop = { name = "Vrtnarska delavnica", cost = { gold = 295, wood = 170, stone = 125, iron = 6 }, upkeep = 5, qualityBonus = 5 },
    shears_house = { name = "Vrtnarska hiša", cost = { gold = 1100, wood = 340, stone = 250, silver = 6, iron = 6 }, upkeep = 23, qualityBonus = 18 },
    master_shears_atelier = { name = "Mojstrski vrtnarski atelje", cost = { gold = 2880, wood = 400, stone = 495, silver = 32, gold = 6 }, upkeep = 67, qualityBonus = 30 },
    sovereign_garden_palace = { name = "Suverena vrtnarska palača", cost = { gold = 12480, wood = 610, stone = 805, gold = 80, jewel = 18 }, upkeep = 246, qualityBonus = 55, prestigeBonus = 50 },
}
PruningShearsMaker.ironStock = 12; PruningShearsMaker.bronzeStock = 10; PruningShearsMaker.woodStock = 14; PruningShearsMaker.leatherStock = 10; PruningShearsMaker.silverStock = 8; PruningShearsMaker.goldStock = 6; PruningShearsMaker.jewelStock = 4; PruningShearsMaker.pearlStock = 4
PruningShearsMaker.productStock = {}; PruningShearsMaker.buildings = {}; PruningShearsMaker.maker = nil; PruningShearsMaker.activeMaking = {}; PruningShearsMaker.totalProducts = 0; PruningShearsMaker.dayTimer = 0
function PruningShearsMaker.init() PruningShearsMaker.ironStock=12; PruningShearsMaker.bronzeStock=10; PruningShearsMaker.woodStock=14; PruningShearsMaker.leatherStock=10; PruningShearsMaker.silverStock=8; PruningShearsMaker.goldStock=6; PruningShearsMaker.jewelStock=4; PruningShearsMaker.pearlStock=4; PruningShearsMaker.productStock={}; PruningShearsMaker.buildings={}; PruningShearsMaker.maker=nil; PruningShearsMaker.activeMaking={}; PruningShearsMaker.totalProducts=0; PruningShearsMaker.dayTimer=0; print("[PruningShearsMaker] Royal Pruning Shears Maker System initialized (6 products, 4 buildings)") end
function PruningShearsMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PruningShearsMaker.maker={name=n or ("Vrtnar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vrtnar najet: %s (spretnost: %d)",PruningShearsMaker.maker.name,s),"success") end; return true end
function PruningShearsMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PruningShearsMaker.build(id) local ok,e=PruningShearsMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PruningShearsMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PruningShearsMaker.getQualityBonus() local b=0; for _,bd in ipairs(PruningShearsMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PruningShearsMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and PruningShearsMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and PruningShearsMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and PruningShearsMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and PruningShearsMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and PruningShearsMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PruningShearsMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PruningShearsMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PruningShearsMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PruningShearsMaker.buildings==0 then return false,"Potrebna vrtnarska delavnica" end; if not PruningShearsMaker.maker then return false,"Potreben vrtnar" end; return true end
function PruningShearsMaker.make(pt,qty) qty=qty or 1; local ok,e=PruningShearsMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then PruningShearsMaker.ironStock=PruningShearsMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then PruningShearsMaker.bronzeStock=PruningShearsMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then PruningShearsMaker.woodStock=PruningShearsMaker.woodStock-d.woodCost*qty end; if d.leatherCost then PruningShearsMaker.leatherStock=PruningShearsMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then PruningShearsMaker.silverStock=PruningShearsMaker.silverStock-d.silverCost*qty end; if d.goldCost then PruningShearsMaker.goldStock=PruningShearsMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PruningShearsMaker.jewelStock=PruningShearsMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PruningShearsMaker.pearlStock=PruningShearsMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PruningShearsMaker.maker then t=math.max(1,t-math.floor(PruningShearsMaker.maker.skill/13)) end; table.insert(PruningShearsMaker.activeMaking,{id="shears_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PruningShearsMaker.completeMaking(m) local q=1.0+(PruningShearsMaker.getQualityBonus()/100); if PruningShearsMaker.maker then q=q+(PruningShearsMaker.maker.skill/140) end; q=math.min(2.5,q); PruningShearsMaker.productStock[m.productType]=(PruningShearsMaker.productStock[m.productType] or 0)+m.quantity; PruningShearsMaker.totalProducts=PruningShearsMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PruningShearsMaker.maker then PruningShearsMaker.maker.itemsMade=PruningShearsMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PruningShearsMaker.maker.skill=math.min(100,PruningShearsMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Škarje izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"shears.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function PruningShearsMaker.update(dt) if not _G.state then return end; PruningShearsMaker.dayTimer=PruningShearsMaker.dayTimer+dt; if PruningShearsMaker.dayTimer>=30 then PruningShearsMaker.dayTimer=0; for i=#PruningShearsMaker.activeMaking,1,-1 do local m=PruningShearsMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PruningShearsMaker.completeMaking(m); table.remove(PruningShearsMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PruningShearsMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PruningShearsMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PruningShearsMaker.getStats() return {ironStock=PruningShearsMaker.ironStock,bronzeStock=PruningShearsMaker.bronzeStock,woodStock=PruningShearsMaker.woodStock,leatherStock=PruningShearsMaker.leatherStock,silverStock=PruningShearsMaker.silverStock,goldStock=PruningShearsMaker.goldStock,jewelStock=PruningShearsMaker.jewelStock,pearlStock=PruningShearsMaker.pearlStock,productStock=PruningShearsMaker.productStock,numBuildings=#PruningShearsMaker.buildings,hasMaker=PruningShearsMaker.maker~=nil,makerName=PruningShearsMaker.maker and PruningShearsMaker.maker.name or "—",makerSkill=PruningShearsMaker.maker and PruningShearsMaker.maker.skill or 0,activeMaking=#PruningShearsMaker.activeMaking,totalProducts=PruningShearsMaker.totalProducts} end
return PruningShearsMaker
